// A small CSV writer (RFC 4180 style) for spreadsheet exports. Pure
// functions: callers pass data in and get a string back; nothing here reads
// or changes app state.

/** Byte order mark. Lets Excel detect UTF-8, so "ñ" and "₱" display correctly. */
export const UTF8_BOM = "﻿";

/** Windows line endings, which every spreadsheet app accepts. */
const LINE_BREAK = "\r\n";

export type CsvColumn<Row> = {
  header: string;
  /**
   * "text" cells are user-controlled (descriptions, names) and are
   * neutralized against formula injection. "number" cells are generated by
   * the app and must be plain decimals ("-1250.50") or empty.
   */
  kind: "text" | "number";
  value: (row: Row) => string;
};

/**
 * Leading characters some spreadsheet apps skip before checking for a
 * formula: whitespace (including tab, CR, LF, non-breaking space), ASCII and
 * C1 control characters, zero-width characters, and the BOM.
 */
const IGNORABLE_PREFIX = /^[\s\u0000-\u001f\u007f-\u009f​-‍⁠﻿]*/;

/**
 * Characters that make a cell a formula (=, +, -, @) or a DDE command,
 * plus their full-width forms, which some apps and input methods normalize.
 */
const FORMULA_START = /^[=+\-@＝＋－＠]/;

/**
 * OWASP's recommended defense against CSV (formula) injection: if a text
 * cell could be read as a formula, prefix it with a single quote so the
 * spreadsheet shows it as text. The check looks past leading whitespace
 * and control characters, because a value like " =HYPERLINK(...)" or
 * "\t=1+1" can still be evaluated. Also catches cells starting with tab or
 * CR, which OWASP lists explicitly. Only the exported copy changes; stored
 * records are never touched.
 *
 * Trade-off: harmless text such as "-50 discount" also gets the quote, and
 * Excel and Google Sheets show the quote in the cell. That's the accepted
 * cost of the policy.
 */
export function neutralizeFormula(text: string): string {
  const afterPrefix = text.slice(IGNORABLE_PREFIX.exec(text)![0].length);
  if (FORMULA_START.test(afterPrefix) || /^[\t\r]/.test(text)) {
    return `'${text}`;
  }
  return text;
}

/** Quotes a field only when needed and doubles any embedded quotes. */
export function escapeCsvField(value: string): string {
  // Leading/trailing spaces are quoted too, so apps don't trim them.
  if (/[",\r\n]/.test(value) || /^\s|\s$/.test(value)) {
    return `"${value.replaceAll('"', '""')}"`;
  }
  return value;
}

const DECIMAL = /^-?\d+(\.\d+)?$/;

function formatCell(value: string, kind: CsvColumn<unknown>["kind"]): string {
  if (kind === "number") {
    // Numbers come from the app, never from users; anything else is a bug.
    if (value !== "" && !DECIMAL.test(value)) {
      throw new TypeError("A numeric CSV cell must be a plain decimal number.");
    }
    return value;
  }
  return escapeCsvField(neutralizeFormula(value));
}

/**
 * Header row plus one row per item, joined with CRLF, with a final line
 * break. No BOM; use toCsvDocument for a file. Never mutates `rows`.
 */
export function toCsv<Row>(columns: readonly CsvColumn<Row>[], rows: readonly Row[]): string {
  const header = columns.map((c) => formatCell(c.header, "text")).join(",");
  const lines = rows.map((row) => columns.map((c) => formatCell(c.value(row), c.kind)).join(","));
  return [header, ...lines].join(LINE_BREAK) + LINE_BREAK;
}

/** The complete file contents: BOM + CSV. */
export function toCsvDocument<Row>(columns: readonly CsvColumn<Row>[], rows: readonly Row[]): string {
  return UTF8_BOM + toCsv(columns, rows);
}

/**
 * "spendwise-" + the given parts, lowercased, with anything other than
 * letters, digits, and hyphens replaced, + ".csv". Parts are app-generated
 * (kinds and dates), but this keeps the name valid on every OS regardless.
 */
export function csvFilename(...parts: string[]): string {
  const safe = ["spendwise", ...parts]
    .map((part) => part.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, ""))
    .filter(Boolean)
    .join("-");
  return `${safe}.csv`;
}
